# -*- coding: utf-8 -*-
"""
Generates the complete js/sample-debts-data.js with exact data from 34 screenshots.
"""
import json

debts = []

def add(id, date, grNo, truckNo, to, debtType, dueAmount, debtAmount, debtMode, borrower, receiver, desc="", fromCity="Kishangarh (Raj.)", company="TTC", dotColor="yellow", returned=None):
    if returned is None:
        returned = []
    totalReturned = sum(r.get('amount', 0) for r in returned) if returned else (debtAmount - dueAmount if debtAmount > dueAmount else 0)
    
    parts = date.split('-')
    y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
    displayDate = f"{d:02d}/{m:02d}/{y}"
    
    if m >= 4:
        fy = f"{y}-{y+1}"
    else:
        fy = f"{y-1}-{y}"
        
    month_names = {
        4: "1 Apr", 5: "2 May", 6: "3 Jun", 7: "4 Jul", 8: "5 Aug", 9: "6 Sep",
        10: "7 Oct", 11: "8 Nov", 12: "9 Dec", 1: "10 Jan", 2: "11 Feb", 3: "12 Mar"
    }
    monthKey = month_names.get(m, f"{m} Month")
    
    if "_SMTC" in grNo or "SMTC" in company:
        comp = "SMTC"
    elif "_MTC" in grNo or "MTC" in company:
        comp = "MTC"
    else:
        comp = company or "TTC"
        
    debts.append({
        "id": id,
        "date": date,
        "displayDate": displayDate,
        "fy": fy,
        "monthKey": monthKey,
        "grNo": grNo,
        "truckNo": truckNo,
        "from": fromCity,
        "to": to,
        "company": comp,
        "truckOwner": "Shree Mahaveer Transport Company" if "Mahaveer" in borrower else borrower,
        "debtType": debtType,
        "dueAmount": float(dueAmount),
        "debtAmount": float(debtAmount),
        "totalReturned": float(totalReturned),
        "debtMode": debtMode,
        "borrowerName": borrower,
        "receiverName": receiver,
        "description": desc,
        "dotColor": dotColor,
        "returnedAmounts": returned
    })

