js_content = f"""/**
 * Authentic MTC & TTC Logistics Open Debts & Ledger Register Data
 * Transcribed from 34 Google AppSheet screenshots (2019 - 2027)
 * Total Active Financial Years: 2026-2027, 2025-2026, 2024-2025, 2023-2024, 2022-2023, 2020-2021, 2019-2020
 */

window.SAMPLE_DEBTS_DATA = {json.dumps(debts, indent=2, ensure_ascii=False)};
"""

with open("js/sample-debts-data.js", "w", encoding="utf-8") as f:
    f.write(js_content)

print(f"Generated {len(debts)} ledger debt records in js/sample-debts-data.js")

# Print summary
fys = {}
for d in debts:
    fy = d['fy']
    fys[fy] = fys.get(fy, 0) + d['dueAmount']

print("\n--- Financial Year Due Totals ---")
for fy in sorted(fys.keys(), reverse=True):
    print(f"FY {fy}: Rs. {fys[fy]:,.2f}")
print(f"TOTAL DUE BALANCE: Rs. {sum(fys.values()):,.2f}")
